    "LMGCEBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "GCEstimjmv",
                name = "LMGCE",
                version = c(1,0,0),
                options = options,
                results = LMGCEResults$new(options=options),
                data = data,
