                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' GCE Linear Model
#'
#' 
#' @param run .
#' @param data .
#' @param dep .
#' @param covs .
#' @param factors .
#' @param intercept .
#' @param caseGLM .
#' @param supportMethod .
#' @param ridgeSignalSupport .
#' @param ridgeLambdaMin .
#' @param ridgeLambdaMax .
#' @param ridgeLambdaN .
#' @param M .
#' @param J .
#' @param weight .
#' @param cvNfolds .
#' @param errorMeasure .
#' @param errorMeasureWhich .
#' @param supportSignalVectorMin .
#' @param supportSignalVectorMax .
#' @param supportSignalVectorN .
#' @param noiseSupportMethod .
#' @param twostepsN .
#' @param seed .
#' @param OLS .
#' @param NormEnt .
#' @param bootstrap .
#' @param bootB .
#' @param bootMethod .
#' @param bootCIMethod .
#' @param bootConfLevel .
#' @param method .
#' @param plot1 .
#' @param plot2 .
#' @param plot3 .
#' @param plot4 .
#' @param plot5 .
#' @param plot6 .
#' @param plot7 .
#' @param plotRidge .
#' @param trueCoef .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$text} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reference} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modelSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coefficients} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot1} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot2} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot3} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot4} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot5} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot6} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot7} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$modelSummary$asDF}
#'
#' \code{as.data.frame(results$modelSummary)}
#'
#' @export
LMGCE <- function(
    run = FALSE,
    data,
    dep,
    covs,
    factors,
    intercept = TRUE,
    caseGLM = "D",
    supportMethod = "standardized",
    ridgeSignalSupport = "symm",
    ridgeLambdaMin = 0.001,
    ridgeLambdaMax = 1000,
    ridgeLambdaN = 100,
    M = 3,
    J = 3,
    weight = 0.5,
    cvNfolds = 5,
    errorMeasure = "RMSE",
    errorMeasureWhich = "1se",
    supportSignalVectorMin = 0.3,
    supportSignalVectorMax = 20,
    supportSignalVectorN = 20,
    noiseSupportMethod = "sigma3",
    twostepsN = 1,
    seed = 230676,
    OLS = FALSE,
    NormEnt = FALSE,
    bootstrap = FALSE,
    bootB = 10,
    bootMethod = "residuals",
    bootCIMethod = "percentile",
    bootConfLevel = 0.95,
    method = "dual.BFGS",
    plot1 = TRUE,
    plot2 = TRUE,
    plot3 = TRUE,
    plot4 = FALSE,
    plot5 = FALSE,
    plot6 = FALSE,
    plot7 = FALSE,
    plotRidge = FALSE,
    trueCoef = "") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("LMGCE requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(factors)) factors <- jmvcore::resolveQuo(jmvcore::enquo(factors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(factors), factors, NULL))


    options <- LMGCEOptions$new(
        run = run,
        dep = dep,
        covs = covs,
        factors = factors,
        intercept = intercept,
        caseGLM = caseGLM,
        supportMethod = supportMethod,
        ridgeSignalSupport = ridgeSignalSupport,
        ridgeLambdaMin = ridgeLambdaMin,
        ridgeLambdaMax = ridgeLambdaMax,
        ridgeLambdaN = ridgeLambdaN,
        M = M,
        J = J,
        weight = weight,
        cvNfolds = cvNfolds,
        errorMeasure = errorMeasure,
        errorMeasureWhich = errorMeasureWhich,
        supportSignalVectorMin = supportSignalVectorMin,
        supportSignalVectorMax = supportSignalVectorMax,
        supportSignalVectorN = supportSignalVectorN,
        noiseSupportMethod = noiseSupportMethod,
        twostepsN = twostepsN,
        seed = seed,
        OLS = OLS,
        NormEnt = NormEnt,
        bootstrap = bootstrap,
        bootB = bootB,
        bootMethod = bootMethod,
        bootCIMethod = bootCIMethod,
        bootConfLevel = bootConfLevel,
        method = method,
        plot1 = plot1,
        plot2 = plot2,
        plot3 = plot3,
        plot4 = plot4,
        plot5 = plot5,
        plot6 = plot6,
        plot7 = plot7,
        plotRidge = plotRidge,
        trueCoef = trueCoef)

    analysis <- LMGCEClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

